export function CreatorRasterArt({
  raster,
  offsetX = 0,
  offsetY = 0,
}: {
  raster: Raster;
  offsetX?: number;
  offsetY?: number;
}) {
  return (
    <img
      alt=""
      aria-hidden="true"
      draggable={false}
      src={raster.url}
      style={{
        position: 'absolute',
        pointerEvents: 'none',
        maxWidth: 'none',
        left: raster.x + offsetX,
        top: raster.y + offsetY,
        width: raster.width,
        height: raster.height,
      }}
    />
  );
}
